// Types for the Emscripten module generated by scripts/build_wasm.sh.

export interface LiveSim {
  load(scenarioJson: string): string;
  command(commandJson: string, scenarioJson: string): string;
  advance(steps: number): void;
  network(): string;
  snapshot(seq: number): string;
  metrics(): string;
  replay(): string;
  state(): string;
  speed(): number;
  dt(): number;
  time(): number;
  step(): number;
  scenarioId(): string;
  scenarioName(): string;
  seed(): number;
  controller(): string;
  delete(): void;
}

export interface ExperimentJob {
  start(requestJson: string, scenarioJson: string, id: string): string;
  total(): number;
  done(): number;
  finished(): boolean;
  runNext(): void;
  resultJson(): string;
  resultCsv(): string;
  delete(): void;
}

export interface TrafficEngineModule {
  LiveSim: new () => LiveSim;
  ExperimentJob: new () => ExperimentJob;
  validateScenario(scenarioJson: string): string;
}

declare const createTrafficEngine: () => Promise<TrafficEngineModule>;
export default createTrafficEngine;
